import {suppliers,rates,money,initialState,budgetStats,totalsFor,checks,createRequest,snapshot,approveRequest,payRequest,rejectRequest,reopenRequest,reconcile,setBudget} from './business-domain.mjs';
import {prepareProposal,planCompany,companyScenarios} from './agent-adapter.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState(),filter='all',search='',lastFocus=null,toastTimer;
try{const v=JSON.parse(sessionStorage.getItem('reap-company-v1'));if(v?.version===1&&Array.isArray(v.budgets)&&Array.isArray(v.requests))state=v;}catch{}
function persist(){try{sessionStorage.setItem('reap-company-v1',JSON.stringify(state));}catch{notify('Session storage is unavailable. Keep this tab open to preserve your demo.');}}
function notify(message){$('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',4500);}
const supplier=id=>suppliers.find(s=>s.id===id);const route=()=>location.hash.slice(1)||'overview';
const labels={review:'Needs approval',approved:'Approved',paid:'Ready to reconcile',reconciled:'Reconciled',cancelled:'Cancelled'};
const badge=r=>`<span class="badge ${r.status}">${labels[r.status]}</span>`;
function metrics(){const b=state.budgets.map(b=>budgetStats(state,b.id));return {limit:b.reduce((a,b)=>a+b.limit,0),spent:b.reduce((a,b)=>a+b.spent,0),reserved:b.reduce((a,b)=>a+b.reserved,0),available:b.reduce((a,b)=>a+b.available,0)};}
function heading(title,subtitle,action='New request'){return `<div class="heading"><div><h1>${title}</h1><p class="muted">${subtitle}</p></div>${action?`<button class="btn" data-new="${action==='New payment'?'international':'purchase'}">＋ ${action}</button>`:''}</div>`;}
function stats(){const m=metrics();return `<div class="stats">${[['Available budget',money(m.available),'Across all departments','◴'],['Spent this month',money(m.spent),`${Math.round(m.spent/m.limit*100)}% of ${money(m.limit)} allocated`,'↗'],['Reserved funds',money(m.reserved),'Approved, not yet paid','◈'],['Needs your review',state.requests.filter(r=>r.status==='review').length,'Decisions waiting for you','☷']].map(([l,v,s,i])=>`<div class="stat"><div class="stat-top"><span>${l}</span><span class="stat-icon">${i}</span></div><div class="stat-value amount">${v}</div><div class="stat-foot">${s}</div></div>`).join('')}</div>`;}
function navigation(){return [['overview','◫','Overview'],['requests','↗','Agent requests'],['approvals','☷','Approvals'],['budgets','◴','Budgets & policies'],['suppliers','◎','Suppliers & payments'],['compute','▥','Compute resources'],['accounting','≋','Reconciliation']].map(([id,icon,label])=>`<a class="nav-item ${route()===id?'active':''}" href="#${id}"><span class="nav-icon">${icon}</span>${label}${id==='approvals'?`<span class="count">${state.requests.filter(r=>r.status==='review').length}</span>`:''}</a>`).join('');}
function shell(content){return `<div class="app-shell"><button class="menu-scrim" aria-label="Close navigation"></button><aside class="sidebar"><a href="#overview" class="logo"><b>↗</b>Robin Go<span style="color:#9cae80">.</span></a><div class="workspace-select"><span class="org-icon">◫</span><div><strong>Acme Studio</strong><div class="tiny">Company workspace · Demo</div></div></div><a class="nav-item" href="index.html"><span class="nav-icon">✧</span>Mi agente · Inicio</a><div class="eyebrow nav-label">Workspace</div><nav aria-label="Company navigation">${navigation()}</nav><a class="nav-item" href="expenses.html"><span class="nav-icon">▤</span>Registro de gastos</a><a class="nav-item" href="reap.html"><span class="nav-icon">▣</span>REAP · Conexión</a><div class="side-bottom"><div class="mode-switch" aria-label="Agent context"><a href="#overview" class="active">Company</a><a href="shopping.html#shop">Shopping ↗</a></div><div class="side-user"><span class="avatar">JD</span><div>Jamie Doe<div class="tiny">Finance admin · Demo role</div></div></div></div></aside><div><header class="topbar"><button class="mobile-menu" aria-label="Open navigation">☰</button><div class="top-path">Workspace &nbsp; / &nbsp; <strong>${({overview:'Overview',requests:'Agent requests',approvals:'Approvals',budgets:'Budgets & policies',suppliers:'Suppliers & payments',compute:'Compute resources',accounting:'Reconciliation'})[route()]||'Overview'}</strong></div><a class="mobile-mode" href="shopping.html#shop">Company ⇄ Shopping</a><div class="top-actions"><span class="demo-badge">Demo workspace</span><span class="date">October · Sample period</span><span class="avatar">JD</span></div></header><main class="main">${content}<footer class="bottom-note"><span>Delegate the work. Stay in control.</span><span>Motor adaptado local · Pagos y contabilidad simulados</span></footer></main></div></div>`;}
function requestTable(rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Request / supplier</th><th>Amount · USD</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="row-title">${esc(r.title)}</div><div class="row-sub">${esc(supplier(r.supplierId).name)} · ${esc(r.id)}</div></td><td class="amount">${money(r.total)}${r.currency!=='USD'?`<div class="row-sub">${money(r.amount,r.currency)}</div>`:''}</td><td>${badge(r)}</td><td><button class="btn small outline" data-review="${r.id}">${r.status==='review'?'Review':'Details'} ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">You’re all caught up. No requests in this view.</div>';}
function budgetRows(){return state.budgets.map(b=>{const s=budgetStats(state,b.id);return `<div class="budget-row"><div class="budget-label"><span>${b.name}</span><span>${money(s.spent+s.reserved)} / ${money(b.limit)}</span></div><div class="meter" role="img" aria-label="${b.name}: ${money(s.spent)} spent, ${money(s.reserved)} reserved"><span class="spent" style="width:${Math.min(100,s.spent/b.limit*100)}%"></span><span class="reserved" style="width:${Math.min(100,s.reserved/b.limit*100)}%"></span></div></div>`;}).join('');}
function activity(){return state.events.slice(0,4).map(e=>`<div class="activity"><span class="activity-icon">✓</span><div><p>${esc(e.text)}</p><span class="tiny">${esc(e.time)}</span></div></div>`).join('');}
function overview(){return heading('Your company, in control.','A clear view of your money, resources, and next decisions.')+stats()+`<div class="work-grid"><div><section class="panel panel-pad agent-panel"><div class="agent-intro"><span class="spark">✧</span><div><h2>Delegate to your agent</h2><p class="muted">You set the intent. Your policies set the boundaries.</p></div></div><div class="agent-prompt">What should we take care of today?</div><form id="intent-form" class="agent-input"><textarea name="intent" aria-label="Instructions for your company agent" placeholder="Pay our design partner in Germany, within the marketing budget…" required maxlength="1000"></textarea><button aria-label="Prepare request">↑</button></form><div class="quick-tasks"><button data-new="international">↗ Pay a global supplier</button><button data-new="compute">▥ Manage cloud capacity</button><button data-new="purchase">＋ Purchase for the team</button></div><div class="quick-tasks"><a href="reap.html" class="btn secondary small">Configurar REAP ↗</a><button id="company-demo">✧ Demo: optimizar recursos</button></div><p class="agent-note">Motor híbrido adaptado de tu main.py · Reglas locales, sin IA conversacional.</p></section><section class="panel section-gap"><div class="panel-head panel-pad" style="margin:0"><h2>Ready for your decision <span class="badge review">${state.requests.filter(r=>r.status==='review').length}</span></h2><a class="text-link" href="#approvals">View all →</a></div>${requestTable(state.requests.filter(r=>r.status==='review').slice(0,3))}</section></div><div class="right-column"><section class="panel panel-pad"><div class="panel-head"><h2>Budget health</h2><a href="#budgets" class="text-link">Manage →</a></div>${budgetRows()}<div class="budget-legend"><span><i class="dot"></i>Spent</span><span><i class="dot reserved"></i>Reserved</span></div></section><section class="panel panel-pad section-gap"><div class="panel-head"><h2>Recent activity</h2><span class="tiny">Workspace log</span></div>${activity()}</section></div></div>`;}
function requestPage(approvals=false){const allowed=approvals?['review','approved','cancelled']:['review','approved','paid','reconciled','cancelled'];const rows=state.requests.filter(r=>allowed.includes(r.status)&&(filter==='all'||r.status===filter)&&`${r.title} ${supplier(r.supplierId).name} ${r.id}`.toLowerCase().includes(search.toLowerCase()));return heading(approvals?'A decision, with all the context.':'Your agent’s work, in one place.',approvals?'Review the recipient, amount, and budget before approving.':'Create a request, follow its progress, and review the outcome.')+`<div class="toolbar"><div class="tabs">${['all',...allowed].map(s=>`<button class="tab ${filter===s?'active':''}" data-filter="${s}">${s==='all'?'All':labels[s]}</button>`).join('')}</div><input id="request-search" aria-label="Search requests" placeholder="Search requests…" value="${esc(search)}"></div><section class="panel">${requestTable(rows)}</section>`;}
function budgets(){return heading('Give your agent clear boundaries.','Control allocations and decide when a person needs to step in.','')+`<div class="resource-grid">${state.budgets.map(b=>{const s=budgetStats(state,b.id);return `<section class="panel resource-card"><span class="resource-icon">◴</span><h2>${b.name}</h2><p class="muted">Monthly allocation · USD</p><div class="resource-value">${money(b.limit)}</div><div class="key-value"><span>Spent</span><span>${money(s.spent)}</span></div><div class="key-value"><span>Reserved</span><span>${money(s.reserved)}</span></div><div class="key-value"><span>Available</span><strong>${money(s.available)}</strong></div><button class="btn outline full" data-budget="${b.id}" style="margin-top:20px">Edit allocation</button></section>`;}).join('')}</div><section class="panel panel-pad section-gap"><div class="policy-grid"><div><h2>Approval policy</h2><p class="muted" style="margin-top:12px">These controls define the context sent to your agent. Enforcement must live in your payment backend.</p><div class="callout">Every proposal requires manual approval in this demo. The threshold marks requests that need finance review.</div></div><form id="policy-form"><label class="field">Finance review above (USD)<input name="threshold" type="number" min="0" max="1000000" step="0.01" value="${state.policy.threshold/100}" required></label><label class="check-row"><input name="approvedOnly" type="checkbox" ${state.policy.approvedOnly?'checked':''}>Only allow approved suppliers</label><button class="btn">Save policy</button><div class="form-error" role="alert"></div></form></div></section>`;}
function supplierPage(){return heading('Global partners. One workspace.','See where payments are going and what needs to happen next.','New payment')+`<div class="resource-grid">${suppliers.filter(s=>s.approved).map(s=>`<section class="panel resource-card"><div class="flex-between"><span class="resource-icon">${s.name.split(' ').map(w=>w[0]).join('').slice(0,2)}</span><span class="badge approved">Approved · Demo</span></div><h2>${s.name}</h2><p class="muted">${s.country} · ${s.currency}</p><div class="key-value"><span>Destination</span><span>${s.account}</span></div><button class="btn outline full" style="margin-top:18px" data-supplier="${s.id}">Prepare payment ↗</button></section>`).join('')}</div><section class="panel section-gap"><div class="panel-head panel-pad" style="margin:0"><h2>Payment queue</h2><span class="tiny">Approve first. Execute second.</span></div>${requestTable(state.requests.filter(r=>['approved','paid'].includes(r.status)))}</section>`;}
function computePage(){return heading('Let capacity grow. Keep spend bounded.','Set operating limits for the infrastructure your agent manages.','')+`<div class="policy-grid"><section class="panel panel-pad"><div class="panel-head"><h2>Production cluster</h2><span class="badge ${state.compute.enabled?'approved':'cancelled'}">${state.compute.enabled?'Scaling enabled':'Scaling paused'}</span></div><div class="resource-value">${state.compute.utilization}% <span class="muted">sample utilization</span></div><div class="meter" role="img" aria-label="Sample utilization 72 percent"><span class="spent" style="width:${state.compute.utilization}%"></span></div><div class="key-value"><span>Provider</span><span>Compute Cloud</span></div><div class="key-value"><span>Current instances</span><span>6 · Sample</span></div><div class="key-value"><span>Current daily spend</span><span>$96.00 · Sample</span></div><div class="key-value"><span>Daily ceiling</span><strong>${money(state.compute.cap)}</strong></div><div class="callout">No cloud changes run automatically in this preview. Simulate a capacity request to see how limits affect a proposal.</div><button class="btn full" id="simulate-scale" ${!state.compute.enabled?'disabled':''}>Simulate capacity request →</button><div id="compute-error" role="alert"></div></section><form class="panel panel-pad" id="compute-form"><h2 style="font-size:17px">Operating limits</h2><label class="check-row"><input name="enabled" type="checkbox" ${state.compute.enabled?'checked':''}>Allow agent to propose scaling</label><label class="field">Daily spend cap (USD)<input name="cap" type="number" min="96" max="10000" step="0.01" required value="${state.compute.cap/100}"></label><label class="field">Maximum instances<input name="instances" type="number" min="6" max="100" step="1" required value="${state.compute.maxInstances}"></label><p class="muted">The ceiling must cover the sample baseline of 6 instances at $96/day. Proposals remain subject to the Engineering budget.</p><button class="btn" style="margin-top:20px">Save limits</button><div class="form-error" role="alert"></div></form></div>`;}
function accounting(){const rows=state.requests.filter(r=>['paid','reconciled'].includes(r.status)&&(filter==='all'||filter==='missing'&&!r.receipt||r.status===filter));return heading('From payment to the books.','Match evidence, assign an account, and close the loop.','')+`<div class="toolbar"><div class="tabs">${[['all','All payments'],['paid','Needs reconciliation'],['missing','Missing evidence'],['reconciled','Reconciled']].map(([id,l])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}">${l}</button>`).join('')}</div><button class="btn outline" id="export-ledger">↓ Export ledger CSV</button></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Payment</th><th>Amount · USD</th><th>Evidence</th><th>Ledger</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="row-title">${esc(r.title)}</div><div class="row-sub">${esc(r.invoice)}</div></td><td>${money(r.total)}</td><td><span class="badge ${r.receipt?'approved':'review'}">${r.receipt?'Reference available':'Missing invoice'}</span></td><td>${r.status==='reconciled'?`<span class="ledger-tag">${esc(r.ledgerAccount)}</span>`:'Not posted'}</td><td><button class="btn small outline" data-reconcile="${r.id}">${r.status==='reconciled'?'View':'Reconcile'} ↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No payments in this view.</td></tr>'}</tbody></table></div></section><div class="callout">Demo reconciliation records a local match. A real accounting connector should verify the invoice, payment, currency, and ledger before posting.</div>`;}
function render(){const pages={overview,requests:()=>requestPage(false),approvals:()=>requestPage(true),budgets,suppliers:supplierPage,compute:computePage,accounting};$('#workspace').innerHTML=shell((pages[route()]||overview)());bind();}
function drawer(title,content){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="drawer-backdrop"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" tabindex="-1"><header class="drawer-header"><div><div class="eyebrow">Company workspace</div><h2 id="drawer-title">${title}</h2></div><button class="close" aria-label="Close panel">×</button></header>${content}</section></div>`;document.body.style.overflow='hidden';$('.close').onclick=closeDrawer;$('.drawer-backdrop').onclick=e=>{if(e.target===$('.drawer-backdrop'))closeDrawer();};$('.drawer').focus();}
function closeDrawer(){ $('#overlay').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
function showError(error){const el=$('#dialog-error');if(el){el.className='error';el.textContent=error.message||String(error);}}
function taskForm(type='purchase',instructions='',sid=''){const defaultSupplier=sid||(type==='international'?'s1':type==='compute'?'s2':'s3');drawer('Give your agent a task',`<p class="muted">Describe the outcome and set the limits. You’ll review the proposed spend before anything happens.</p><form id="task-form"><label class="field">Task type<select name="type">${[['purchase','Purchase goods or services'],['international','Pay an international supplier'],['compute','Request compute capacity']].map(([v,l])=>`<option value="${v}" ${type===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Task title<input name="title" required maxlength="100" placeholder="e.g. Pay October design invoice"></label><label class="field">Instructions for your agent<textarea name="description" required maxlength="1000" placeholder="What needs to happen, by when, and with which constraints?">${esc(instructions)}</textarea></label><div class="form-grid"><label class="field">Department budget<select name="department">${state.budgets.map(b=>`<option value="${b.id}" ${b.id===(type==='compute'?'engineering':type==='international'?'marketing':'operations')?'selected':''}>${b.name}</option>`).join('')}</select></label><label class="field">Supplier<select name="supplierId">${suppliers.map(s=>`<option value="${s.id}" ${s.id===defaultSupplier?'selected':''}>${s.name}${s.approved?'':' · Not verified'}</option>`).join('')}</select></label></div><label class="field">Proposed amount (<span id="currency-label">${supplier(defaultSupplier).currency}</span>)<input name="amount" type="number" min="0.01" max="10000000" step="0.01" required placeholder="0.00"></label><div class="callout" id="estimate">Add an amount to preview its impact on the budget.</div><div id="dialog-error" role="alert"></div><button class="btn full" type="submit">Prepare proposal →</button><p class="tiny" style="margin-top:12px">Demo only. Instructions are not sent to an external agent.</p></form>`);
const form=$('#task-form');const update=()=>{const d=new FormData(form),s=supplier(d.get('supplierId'));$('#currency-label').textContent=s.currency;const amount=Math.round(Number(d.get('amount'))*100);if(amount>0){const t=totalsFor(amount,s.currency,d.get('type'));$('#estimate').textContent=`Estimated budget impact: ${money(t.total)} USD${s.currency==='USD'?'':` · Sample FX: 1 ${s.currency} = ${rates[s.currency]} USD`}${t.fee?' · Includes $18 demo transfer fee':''}`;}};form.addEventListener('input',()=>{try{update();}catch{}});form.addEventListener('change',update);form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const d=Object.fromEntries(new FormData(form)),s=supplier(d.supplierId);d.amount=Math.round(Number(d.amount)*100);d.currency=s.currency;const decision=await prepareProposal({mode:'company',intent:d.type,instructions:d.description,context:d,state});const r=createRequest(state,{...d,agentDecision:decision});persist();render();review(r.id);}catch(error){showError(error);button.disabled=false;}};}
function review(id){const r=state.requests.find(r=>r.id===id);if(!r)return;const s=supplier(r.supplierId),frozen=snapshot(r);drawer('Review the proposed spend',`${badge(r)}<h3 class="subheading">${esc(r.title)}</h3><p class="muted">${esc(r.description)}</p>${r.agentDecision?`<div class="agent-thread">✧ ${esc(r.agentDecision.message)}</div>`:''}<div class="locked">◈ Review snapshot · Changes require a fresh approval. Demo checks run locally.</div><section class="panel panel-pad"><div class="key-value"><span>Recipient</span><strong>${s.name}</strong></div><div class="key-value"><span>Destination</span><span>${s.account} · ${s.country}</span></div><div class="key-value"><span>Supplier receives</span><span>${money(r.amount,r.currency)}</span></div>${r.currency!=='USD'?`<div class="key-value"><span>Illustrative exchange rate</span><span>1 ${r.currency} = ${rates[r.currency]} USD</span></div>`:''}<div class="key-value"><span>Transfer fee</span><span>${money(r.fee)}</span></div><div class="key-value"><span>Department</span><span>${state.budgets.find(b=>b.id===r.department).name}</span></div><div class="flex-between" style="margin-top:20px"><span class="muted">Total budget impact</span><strong class="total-large">${money(r.total)}</strong></div></section>${['review','approved'].includes(r.status)?`<h3 class="subheading">Policy checks</h3>${checks(state,r).map(c=>`<div class="check ${c.pass?'':'fail'}"><span class="symbol">${c.pass?'✓':'!'}</span><div>${c.name}<div class="tiny">${c.detail}</div></div></div>`).join('')}`:''}<div id="dialog-error" role="alert"></div>${r.status==='review'?`<label class="check-row"><input id="approve-consent" type="checkbox">I approve this recipient and the ${money(r.total)} demo budget impact.</label><div class="actions"><button class="btn" id="approve-request">Approve & reserve</button><button class="btn outline" id="cancel-request">Reject request</button></div>`:r.status==='approved'?`<div class="callout">Funds are reserved. Payment execution is a separate step. No real transfer will be made.</div><div class="actions"><button class="btn" id="pay-request">Simulate payment →</button><button class="btn outline" id="reopen-request">Request fresh review</button><button class="btn danger" id="cancel-request">Cancel</button></div>`:`<div class="status-card">✓ ${labels[r.status]}${r.ledgerAccount?' · '+esc(r.ledgerAccount):''}</div>${r.status==='paid'?'<button class="btn full" id="open-reconcile">Continue to reconciliation →</button>':''}`}<p class="tiny" style="margin-top:20px">${esc(r.id)} · Prototype only. Signed, tamper-resistant checkout must be enforced by your backend.</p>`);
$('#approve-request')?.addEventListener('click',()=>{try{if(!$('#approve-consent').checked)throw Error('Confirm the recipient and amount first');approveRequest(state,id,frozen);persist();render();review(id);notify('Approved. The amount is now reserved.');}catch(e){showError(e);}});$('#pay-request')?.addEventListener('click',()=>{try{payRequest(state,id);persist();render();review(id);notify('Demo payment completed. Ready to reconcile.');}catch(e){showError(e);}});$('#reopen-request')?.addEventListener('click',()=>{try{reopenRequest(state,id);persist();render();review(id);}catch(e){showError(e);}});$('#cancel-request')?.addEventListener('click',()=>{try{rejectRequest(state,id);persist();closeDrawer();render();notify('Request cancelled. Reserved funds released.');}catch(e){showError(e);}});$('#open-reconcile')?.addEventListener('click',()=>reconcileForm(id));}
function reconcileForm(id){const r=state.requests.find(r=>r.id===id);drawer(r.status==='reconciled'?'Reconciliation details':'Close the accounting loop',`<h3 class="subheading">${esc(r.title)}</h3><div class="key-value"><span>Payment</span><strong>${money(r.total)}</strong></div><div class="key-value"><span>Supplier</span><span>${supplier(r.supplierId).name}</span></div>${r.status==='reconciled'?`<div class="callout">Matched to ${esc(r.ledgerAccount)}<br>Invoice reference: ${esc(r.invoice)}</div>`:`<form id="reconcile-form"><label class="field">Invoice reference<input name="invoice" required maxlength="100" value="${r.receipt?esc(r.invoice):''}" placeholder="Enter the invoice reference"></label><label class="field">Ledger account<select name="account" required><option value="">Select an account</option>${['6100 Office & operations','6200 Software & cloud','6300 Professional services'].map(a=>`<option ${a.startsWith(r.type==='compute'?'6200':r.type==='international'?'6300':'6100')?'selected':''}>${a}</option>`).join('')}</select></label><label class="check-row"><input name="verified" type="checkbox" required>I’ve reviewed the demo invoice reference, supplier, and payment amount.</label><div class="callout">This records a local demo match. It does not upload an invoice or post to an accounting system.</div><div id="dialog-error" role="alert"></div><button class="btn full">Match & mark reconciled</button></form>`}`);$('#reconcile-form')?.addEventListener('submit',e=>{e.preventDefault();try{const d=new FormData(e.target);if(!d.get('invoice').trim())throw Error('Add an invoice reference');const previous={invoice:r.invoice,receipt:r.receipt};r.invoice=d.get('invoice').trim();r.receipt=true;try{reconcile(state,id,d.get('account'));}catch(error){Object.assign(r,previous);throw error;}persist();closeDrawer();render();notify('Demo ledger updated. Payment reconciled.');}catch(error){showError(error);}});}
function editBudget(id){const b=budgetStats(state,id);drawer('Edit '+b.name+' budget',`<p class="muted">Keep the allocation above funds already spent or reserved.</p><form id="budget-form"><label class="field">Monthly allocation (USD)<input name="limit" type="number" step="0.01" min="${(b.spent+b.reserved)/100}" max="10000000" value="${b.limit/100}" required></label><div class="callout">Minimum allocation: ${money(b.spent+b.reserved)}</div><div id="dialog-error" role="alert"></div><button class="btn full">Save allocation</button></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();try{setBudget(state,id,Math.round(Number(new FormData(e.target).get('limit'))*100));persist();closeDrawer();render();notify('Department budget updated.');}catch(error){showError(error);}};}
function exportLedger(){const rows=state.requests.filter(r=>r.status==='reconciled');if(!rows.length){notify('Reconcile a payment first to create a ledger export.');return;}const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';const csv=[['Request','Supplier','Invoice','Ledger account','Amount USD','Status'],...rows.map(r=>[r.id,supplier(r.supplierId).name,r.invoice,r.ledgerAccount,(r.total/100).toFixed(2),'Demo reconciled'])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='reap-demo-ledger.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bind(){$('#company-demo')?.addEventListener('click',companyDemo);document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>taskForm(b.dataset.new));document.querySelectorAll('[data-supplier]').forEach(b=>b.onclick=()=>taskForm(supplier(b.dataset.supplier).currency==='USD'?'purchase':'international','',b.dataset.supplier));document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>review(b.dataset.review));document.querySelectorAll('[data-budget]').forEach(b=>b.onclick=()=>editBudget(b.dataset.budget));document.querySelectorAll('[data-reconcile]').forEach(b=>b.onclick=()=>reconcileForm(b.dataset.reconcile));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});$('#request-search')?.addEventListener('input',e=>{search=e.target.value;const start=e.target.selectionStart;render();$('#request-search').focus();$('#request-search').setSelectionRange(start,start);});$('.mobile-menu').onclick=()=>document.body.classList.add('menu-open');$('.menu-scrim').onclick=()=>document.body.classList.remove('menu-open');$('#intent-form')?.addEventListener('submit',e=>{e.preventDefault();const v=new FormData(e.target).get('intent');taskForm(/cloud|compute|capacity/i.test(v)?'compute':/pay|supplier|invoice/i.test(v)?'international':'purchase',v);});$('#policy-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);state.policy={threshold:Math.round(Number(d.get('threshold'))*100),approvedOnly:d.has('approvedOnly')};persist();notify('Demo policy updated.');});$('#compute-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);state.compute={...state.compute,enabled:d.has('enabled'),cap:Math.round(Number(d.get('cap'))*100),maxInstances:Number(d.get('instances'))};persist();render();notify('Compute limits saved for future proposals.');});$('#simulate-scale')?.addEventListener('click',()=>{const error=$('#compute-error');if(state.compute.cap<12800||state.compute.maxInstances<8){error.className='error';error.textContent='Adding two instances needs at least 8 allowed instances and a $128 daily cap. Update limits or keep current capacity.';return;}const r=createRequest(state,{type:'compute',title:'Add two production instances',description:'Demo capacity proposal: grow from 6 to 8 instances for one day at $32 incremental cost. Projected total daily spend: $128.',department:'engineering',supplierId:'s2',currency:'USD',amount:3200,projectedDaily:12800,instances:8});persist();render();review(r.id);});$('#export-ledger')?.addEventListener('click',exportLedger);}

function companyDemo(){
 let settings={objective:'balanced',reserve:500000,capacity:3,horizon:7},result=null;
 drawer('Demo · Optimizar recursos',`<p class="muted">Tu controlador híbrido, adaptado a decisiones empresariales. Revisa el plan antes de crear propuestas; no se ejecutan pagos.</p><form id="hybrid-form"><div class="form-grid"><label class="field">Objetivo<select name="objective"><option value="balanced">Equilibrar prioridades</option><option value="frugal">Priorizar ahorro potencial</option><option value="speed">Priorizar rapidez</option></select></label><label class="field">Reserva de efectivo (USD)<input name="reserve" type="number" min="0" step="0.01" value="5000" required></label><label class="field">Máximo de tareas<input name="capacity" type="number" min="1" max="4" value="3" required></label><label class="field">Plazo (días)<input name="horizon" type="number" min="1" max="30" value="7" required></label></div><button class="btn full">Calcular plan</button></form><div id="dialog-error" role="alert"></div><div id="hybrid-results" aria-live="polite"></div>`);
 function calculate(){try{result=planCompany(state,settings);$('#dialog-error').className='';$('#dialog-error').textContent='';$('#hybrid-results').innerHTML=`<div class="hybrid-budget"><span>Propuesto: <strong>${money(result.committed)}</strong></span><span>Reserva: <strong>${money(result.reserve)}</strong></span></div><p class="hybrid-why">Heurística de prioridad y esfuerzo. Conserva planes viables y no gasta ahorros futuros. ${result.selected.length} tareas recomendadas.</p>${result.selected.map(c=>`<section class="hybrid-result"><h3>${esc(c.title)}</h3><p>${money(c.cost)} · ${esc(c.reason)}</p>${c.savings?`<p>Ahorro hipotético: ${money(c.savings)}/mes. No garantizado.</p>`:''}</section>`).join('')||'<div class="callout">Ninguna acción cabe en tus límites actuales. Reduce la reserva, amplía el plazo o revisa las propuestas existentes.</div>'}${result.selected.length?'<button class="btn full" id="apply-hybrid">Crear propuestas para revisar →</button>':''}<h3 class="subheading">Pospuesto o bloqueado</h3>${result.deferred.map(c=>`<div class="check"><span>↳</span><div>${esc(c.title)}<div class="tiny">${esc(c.reason)}</div></div></div>`).join('')||'<p class="tiny">Nada pendiente.</p>'}<p class="tiny">La reserva limita este plan; no cambia la política global de pagos.</p>`;$('#apply-hybrid')?.addEventListener('click',()=>{try{const fresh=planCompany(state,settings);if(!fresh.selected.length)throw Error('El estado cambió. Calcula un plan nuevo.');const ids=[];for(const c of fresh.selected){const source=companyScenarios.find(s=>s.id===c.id);const r=createRequest(state,{...source,agentScenario:c.id,agentDecision:{message:'Seleccionado por el motor híbrido: '+c.reason}});ids.push(r.id);}persist();closeDrawer();location.hash='requests';render();notify(`${ids.length} propuestas creadas. Revisa cada una antes de aprobar.`);}catch(error){showError(error);}});}catch(error){showError(error);$('#hybrid-results').innerHTML='';}}
 $('#hybrid-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);settings={objective:d.get('objective'),reserve:Math.round(Number(d.get('reserve'))*100),capacity:Number(d.get('capacity')),horizon:Number(d.get('horizon'))};calculate();};calculate();
}

window.addEventListener('hashchange',()=>{filter='all';search='';closeDrawer();document.body.classList.remove('menu-open');render();window.scrollTo(0,0);});document.addEventListener('keydown',e=>{if(!$('.drawer'))return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const focus=[...$('.drawer').querySelectorAll('button:not(:disabled),a,input,select,textarea')];if(!focus.length)return;const first=focus[0],last=focus.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.drawer'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});render();

// Direct handoff from the Robin home proposal; opens review only.
if(new URLSearchParams(location.search).get("demo")==="resources")companyDemo();
